package com.bank.amount;

import java.util.Arrays;
import java.util.logging.*;

public class TopKDemo {
    private static final Logger log = Logger.getLogger(TopKDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Transaction amounts (scaled) across a day; 500 and 1000 are frequent
        int[] amounts = {500, 1000, 500, 2000, 1000, 500, 3000, 1000, 2000};
        int k = 2;

        FrequencyService service = new FrequencyService();
        int[] topK = service.topKFrequent(amounts, k);

        log.info("Finding the top " + k + " most frequent transaction amounts");
        log.info("Top K amounts -> " + Arrays.toString(topK));
    }
}

// ─── Would be in service/FrequencyService.java ───
class FrequencyService {
    // Frequency map + size-K min-heap. O(n log K) time.
    int[] topKFrequent(int[] nums, int k) {
        java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);  // count occurrences

        // Min-heap on frequency: smallest frequency sits on top for eviction
        java.util.PriorityQueue<Integer> heap =
            new java.util.PriorityQueue<>((a, b) -> freq.get(a) - freq.get(b));

        for (int key : freq.keySet()) {
            heap.offer(key);
            if (heap.size() > k) {
                heap.poll();      // drop the least frequent, keep K largest
            }
        }

        int[] result = new int[k];
        for (int i = k - 1; i >= 0; i--) {
            result[i] = heap.poll();  // heap yields ascending frequency
        }
        return result;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
